#!/bin/sh\n# apocalypse‑quote generator\n\nquotes=(\n"Even the sun will rise on the ashes."\n"The last bunker is just a hallway."\n"Hope is the most dangerous weapon."\n"Remember: water is life, but fire is fun."\n"Silence is louder than the sirens."\n)\n\n# Use SEED env var for deterministic selection\nif [ -n "$SEED" ]; then\n  idx=$(( SEED % ${#quotes[@]} ))\nelse\n  # Generate a pseudo‑random index using awk (sh has no $RANDOM)\n  idx=$(awk -v max=${#quotes[@]} 'BEGIN{ srand(); print int(rand()*max) }')\nfi\n\necho "${quotes[$idx]}"
